#include <getopt.h>
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
/* Source-derived parser probe after procps consumes the signal selector.
 * Never calls kill or sends a signal. */
int main(int argc, char **argv) {
  static const struct option options[] = {{0,0,0,0}};
  opterr=0;
  int flag=getopt_long(argc,argv,"l::Ls:hVq:",options,0);
  if (flag=='?' && isdigit(optopt)) {
    printf("%ld\n", (long)('0'-optopt)); return 0;
  }
  if (flag==-1 && optind<argc) {
    printf("%ld\n",strtol(argv[optind],0,10)); return 0;
  }
  return 2;
}
